<template><MerchantShell title="门店订单详情" :manager="manager"><template v-if="order"><view class="merchant-card"><view class="merchant-row"><text class="merchant-subtitle">{{ order._status._title }}</text><text class="merchant-amount">¥{{ order.pay_price }}</text></view><text>{{ order._status._msg }}</text><text v-if="stopTime" class="merchant-note">付款截止 {{ merchantDate(stopTime) }}</text><view class="merchant-divider" /><view class="merchant-row"><text>订单号</text><text class="merchant-link" @tap="copy(order.order_id)">{{ order.order_id }} · 复制</text></view><view class="merchant-row"><text>创建时间</text><text>{{ order._add_time }}</text></view><view class="merchant-row"><text>支付状态</text><text>{{ order.paid ? '已支付' : '未支付' }}</text></view><view class="merchant-row"><text>支付方式</text><text>{{ order._status._payType || order.pay_type }}</text></view><view v-if="order.paid" class="merchant-row"><text>支付时间</text><text>{{ order._pay_time }}</text></view><text class="merchant-note">{{ order.store.name }} · {{ order.type_name }}</text></view><view class="merchant-card"><text class="merchant-subtitle">下单客户</text><view class="merchant-row"><image v-if="order.customer.avatar" :src="order.customer.avatar" class="merchant-cart-image" mode="aspectFill" /><view class="merchant-stack"><text>{{ order.customer.nickname }} <text v-if="order.customer.pay_vip_status">· 付费会员</text></text><text v-if="order.customer.level_name">{{ order.customer.level_name }}</text><text class="merchant-note">UID {{ order.customer.uid }} · {{ order.user_phone }}</text></view></view></view><view v-if="order.product_type===0" class="merchant-card"><text class="merchant-subtitle">收件信息</text><text>{{ order.real_name }} · {{ order.user_phone }}</text><view v-if="order.shipping_type===1" class="merchant-note">{{ order.user_address }}</view></view><view v-if="order.split.length" class="merchant-card"><text class="merchant-subtitle">拆单履约包裹</text><view v-for="child in order.split" :key="child.id" class="merchant-row merchant-click" @tap="manager.go('orderDetail',{orderId:child.order_id})"><view class="merchant-stack"><text class="merchant-link">{{ child.order_id }}</text><text class="merchant-note">{{ child.total_num }} 件 · 状态 {{ child.status }} · {{ child.delivery_name }} {{ child.delivery_id }}</text></view><text>¥{{ child.pay_price }}</text></view></view><view class="merchant-card"><text class="merchant-subtitle">订单商品</text><MerchantCart v-for="cart in order.cartInfo" :key="cart.id" :cart="cart"><text v-if="writeoffCount(cart)" class="merchant-note">已核销 {{ writeoffCount(cart) }} 件</text><text v-if="surplusCount(cart)" class="merchant-note">剩余可核销 {{ surplusCount(cart) }} 件</text></MerchantCart></view><view v-if="order.give_coupon.length||order.give_integral" class="merchant-card"><text class="merchant-subtitle">下单赠送</text><text v-if="order.give_integral">赠送积分 {{ order.give_integral }}</text><view v-for="coupon in order.give_coupon" :key="coupon.id">{{ coupon.coupon_title }}</view></view><view v-if="order.mark||order.remark" class="merchant-card"><text class="merchant-subtitle">备注</text><view v-if="order.mark">客户留言：{{ order.mark }}</view><view v-if="order.remark">商家备注：{{ order.remark }}</view></view><view v-if="order.virtual_info||order.fictitious_content" class="merchant-card"><text class="merchant-subtitle">虚拟发货内容</text><text>{{ order.virtual_info || order.fictitious_content }}</text></view><view v-if="formRows.length" class="merchant-card"><text class="merchant-subtitle">订单填写信息</text><view v-for="(field,index) in formRows" :key="index" class="merchant-row"><text>{{ field.name }}</text><text>{{ field.value }}</text></view></view><view v-if="refundExplanation || refundImages.length" class="merchant-card"><text class="merchant-subtitle">退款说明及凭证</text><text>{{ refundExplanation }}</text><view class="merchant-images"><image v-for="pic in refundImages" :key="pic" :src="pic" mode="aspectFill" @tap="preview(pic)" /></view></view><view v-if="order.delivery_type" class="merchant-card"><text class="merchant-subtitle">配送信息</text><view>{{ order._status._deliveryType || order.delivery_type }}</view><view>{{ order.delivery_name }}</view><text v-if="order.delivery_id" class="merchant-link" @tap="copy(order.delivery_id)">{{ order.delivery_id }} · 复制</text></view><view class="merchant-card"><text class="merchant-subtitle">费用明细</text><view v-for="line in priceLines" :key="line.label" class="merchant-row"><text>{{ line.label }}</text><text>{{ line.prefix }}¥{{ line.amount }}</text></view><view v-for="promotion in order.promotions_detail" :key="`${promotion.promotions_id}:${promotion.product_id}`" class="merchant-row"><text>{{ promotionTitle(promotion) }}</text><text>-¥{{ promotion.promotions_price }}</text></view><view class="merchant-divider" /><view class="merchant-row"><text>实付款</text><text class="merchant-amount">¥{{ order.pay_price }}</text></view></view><view v-if="order.refund.length" class="merchant-card"><text class="merchant-subtitle">售后申请</text><view v-for="refund in order.refund" :key="refund.id" class="merchant-row"><text>申请 {{ refund.id }} · {{ refund.refund_num }} 件 · ¥{{ refund.refund_price }}</text><button :disabled="!order.actions.refund_decide.available" @tap="manager.go('refund',{orderId:order.order_id,refund_id:refund.id,mode:'review'})">查看并处理</button></view></view><view class="merchant-card"><MerchantActions :item="order" :capabilities="manager.context.value?.data.capabilities" :busy="manager.busy.value" detail @action="openAction" /></view><MerchantOperationPanel v-if="editingAction" :manager="manager" :order="order" :action="editingAction" @close="editingAction=null" @saved="saved" /></template></MerchantShell></template>
<script setup lang="ts">
import { computed,ref } from 'vue';import MerchantShell from '@/components/merchantOrders/MerchantShell.vue';import MerchantCart from '@/components/merchantOrders/MerchantCart.vue';import MerchantActions from '@/components/merchantOrders/MerchantActions.vue';import MerchantOperationPanel from '@/components/merchantOrders/MerchantOperationPanel.vue';import { useMerchantOrders } from '@/composables/useMerchantOrders';import { isMerchantDetail,merchantOrderId,merchantFormRows,merchantDate,merchantMoneySum } from '@/utils/merchantOrders';import type { MerchantOrderDetail,MerchantOrderAction,MerchantOrderCart } from '@/types/merchantOrders';
const order=ref<MerchantOrderDetail|null>(null),editingAction=ref<MerchantOrderAction|null>(null);let orderId='';
const manager=useMerchantOrders({query(query){orderId=query.orderId||query.id||'';},clear(){order.value=null;editingAction.value=null;},async load(controller){const valid=controller.fence();if(!merchantOrderId(orderId))throw Error('订单编号无效');const row=await controller.read(`detail/${encodeURIComponent(orderId)}`,isMerchantDetail);if(!valid())return;if(row.data.order_id!==orderId)throw Error('订单响应不匹配');order.value=row.data;}});
const formRows=computed(()=>merchantFormRows(order.value?.custom_form));
const stopTime=computed(()=>order.value?.stop_time||0);
const refundExplanation=computed(()=>order.value?.refund_reason_wap_explain||order.value?.refund_reason_wap||order.value?.refund_reason||'');
const refundImages=computed(()=>[...(order.value?.refund_img||[]),...(order.value?.refund_goods_img||[])]);
const priceLines=computed(()=>{const value=order.value;return value?[{label:'商品金额',amount:merchantMoneySum([value.total_price,value.vip_true_price]),prefix:''},{label:'运费',amount:value.pay_postage,prefix:''},{label:'会员优惠',amount:value.vip_true_price,prefix:'-'},{label:'优惠券',amount:value.coupon_price,prefix:'-'},{label:'积分抵扣',amount:value.deduction_price,prefix:'-'},{label:'活动优惠',amount:value.promotions_price,prefix:'-'},{label:'首单优惠',amount:value.first_order_price,prefix:'-'}]:[];});
function writeoffCount(cart:MerchantOrderCart){return cart.write_times-cart.write_surplus_times;}function surplusCount(cart:MerchantOrderCart){return cart.write_surplus_times;}
function promotionTitle(value:MerchantOrderDetail['promotions_detail'][number]){return value.title||'促销活动';}
function copy(value:string){if(manager.current()&&order.value)uni.setClipboardData({data:value});}function preview(pic:string){if(manager.current()&&refundImages.value.includes(pic))uni.previewImage({current:pic,urls:refundImages.value});}
function openAction(action:MerchantOrderAction){const value=order.value;if(!value||!value.actions[action].available||!manager.context.value?.data.capabilities[action]||manager.busy.value)return;if(action==='manual_delivery')manager.go('delivery',{orderId:value.order_id});else if(action==='tracking')manager.go('logistics',{orderId:value.order_id});else if(action==='refund_create')manager.go('refund',{orderId:value.order_id,mode:'create'});else if(action==='refund_decide')manager.go('refund',{orderId:value.order_id,mode:'review'});else if(action==='writeoff')manager.operationError.value='请以独立核销身份进入核销工作台，当前管理身份不授予核销权限。';else editingAction.value=action;}
function saved(){editingAction.value=null;void manager.load();}
</script>
